declare(strict_types=1);require __DIR__.'/bootstrap.php';require_admin();$id=(int)($_GET['id']??0);$type=(string)($_GET['type']??'');if(!in_array($type,['original','result'],true)){http_response_code(400);exit('種類が正しくありません');}$st=db()->prepare('SELECT original_path,result_path,device_name FROM seed_count_records WHERE id=?');$st->execute([$id]);$r=$st->fetch();if(!$r){http_response_code(404);exit('記録がありません');}$file=realpath(path_of((string)($type==='original'?$r['original_path']:$r['result_path'])));$root=realpath(path_of('uploads'));if(!$file||!$root||strpos($file,$root.DIRECTORY_SEPARATOR)!==0||!is_file($file)){http_response_code(404);exit('画像がありません');}$mime=(string)(mime_content_type($file)?:'application/octet-stream');$ext=strtolower((string)pathinfo($file,PATHINFO_EXTENSION));$name=preg_replace('/[^A-Za-z0-9_-]/','_',trim((string)$r['device_name']));if($name==='')$name='seed';header('Content-Type: '.$mime);header('Content-Length: '.filesize($file));header('Content-Disposition: attachment; filename="'.$name.'-'.$id.'-'.$type.'.'.$ext.'"');header('X-Content-Type-Options: nosniff');readfile($file);
